import{_ as e,o as a,c as s,a5 as i}from"./chunks/framework.DGp912Ge.js";const g=JSON.parse('{"title":"High Level Command — Python Example","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"software/sdk/python/high-level.md","filePath":"software/sdk/python/high-level.md","lastUpdated":1785209608000}'),o={name:"software/sdk/python/high-level.md"};function n(d,t,l,r,h,c){return a(),s("div",null,[...t[0]||(t[0]=[i(`<h1 id="high-level-command-—-python-example" tabindex="-1">High Level Command — Python Example <a class="header-anchor" href="#high-level-command-—-python-example" aria-label="Permalink to &quot;High Level Command — Python Example&quot;">​</a></h1><p><strong>Source</strong>: <code>rbq_sdk/python/example/sport/rbq_high_level.py</code></p><p>Python port of <a href="/RBQ/software/sdk/cpp/high-level.html"><code>rbq_high_level.cpp</code></a>.<br> Publishes <code>HighLevelCommand</code> at <strong>50 Hz</strong> over DDS, selects gaits from the terminal, and reads joystick velocity setpoints.</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Three concurrent actors:</p><table tabindex="0"><thead><tr><th>Actor</th><th>Rate</th><th>Role</th></tr></thead><tbody><tr><td><strong>Control loop thread</strong></td><td>50 Hz</td><td>Publishes <code>HighLevelCommand</code> with current gait + velocity</td></tr><tr><td><strong>Joystick loop thread</strong></td><td>100 Hz</td><td>Polls joystick and updates velocity setpoints</td></tr><tr><td><strong>Main thread</strong> (terminal)</td><td>blocking</td><td>Reads gait names / IDs from stdin</td></tr></tbody></table><p>At startup the control loop publishes <code>switchControlMode = true</code> once (after 200 ms), enabling <strong>EXT_JOY mode</strong> on the robot stack. Without this, <code>HighLevelCommand</code> is ignored.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li><code>rbq_sdk_py</code> installed — see <a href="/RBQ/software/sdk/python/overview.html">Python SDK Overview</a>.</li><li>A Linux joystick device at <code>/dev/input/js*</code> (required to start).</li><li>Robot stack running (simulation or hardware).</li></ul><h2 id="install-run" tabindex="-1">Install &amp; Run <a class="header-anchor" href="#install-run" aria-label="Permalink to &quot;Install &amp; Run&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> RBQ/rbq_sdk/python</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> RBQ/rbq_sdk/python/example/sport</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rbq_high_level.py</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">networkInterfac</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [joystickPath]</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># e.g.</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rbq_high_level.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> eth0</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rbq_high_level.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> eth0</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/input/js1</span></span></code></pre></div><p>Joystick auto-detection: prefers a device whose name contains &quot;Logitech&quot;, &quot;gamepad&quot;, &quot;Xbox&quot;, or &quot;wireless&quot;, then falls back to the first available <code>js*</code> node.<br> Override via argument or <code>JOY=/dev/input/js1 python3 rbq_high_level.py eth0</code>.</p><h2 id="terminal-commands" tabindex="-1">Terminal commands <a class="header-anchor" href="#terminal-commands" aria-label="Permalink to &quot;Terminal commands&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>list              # print the example&#39;s built-in list</span></span>
<span class="line"><span>standing          # switch to STANDING by name</span></span>
<span class="line"><span>3                 # switch to TROTTING by ID</span></span>
<span class="line"><span>waving            # switch to WAVING by name</span></span></code></pre></div><h2 id="supported-gaits" tabindex="-1">Supported gaits <a class="header-anchor" href="#supported-gaits" aria-label="Permalink to &quot;Supported gaits&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Name</th><th>ID</th><th>Description</th></tr></thead><tbody><tr><td><code>sitting</code></td><td>0</td><td>Robot sits on the ground</td></tr><tr><td><code>standing</code></td><td>1</td><td>Neutral standing posture (default at startup)</td></tr><tr><td><code>trotting</code></td><td>3</td><td>MPC trot gait</td></tr><tr><td><code>trot_stairs</code></td><td>4</td><td>Stair-adaptive trot</td></tr><tr><td><code>waving</code></td><td>5</td><td>Slow walk gait</td></tr><tr><td><code>docking</code></td><td>10</td><td>Auto-docking sequence</td></tr></tbody></table><blockquote><p>The example&#39;s built-in list also prints internal gaits that are not supported. Use only the gaits in the table above.</p></blockquote><h2 id="joystick-velocity-controls" tabindex="-1">Joystick velocity controls <a class="header-anchor" href="#joystick-velocity-controls" aria-label="Permalink to &quot;Joystick velocity controls&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Axis</th><th>Maps to</th><th>Max value</th></tr></thead><tbody><tr><td>Left stick Y (forward)</td><td><code>vel_x</code></td><td>±1.2 m/s</td></tr><tr><td>Left stick X (lateral)</td><td><code>vel_y</code></td><td>±0.5 m/s</td></tr><tr><td>Right stick X (yaw)</td><td><code>omega_z</code></td><td>±60 deg/s</td></tr></tbody></table><p>Deadzone of <strong>0.12</strong> applied before scaling.</p><blockquote><p><strong><code>omega_z</code> units</strong>: sent in <strong>deg/s</strong> — QuadWalk multiplies by D2R internally.</p></blockquote><h2 id="dds-topics" tabindex="-1">DDS topics <a class="header-anchor" href="#dds-topics" aria-label="Permalink to &quot;DDS topics&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Direction</th><th>Topic</th><th>Message type</th></tr></thead><tbody><tr><td>Publish</td><td><code>rt/rbq/cmd/high_level</code></td><td><code>HighLevelCommand_</code></td></tr><tr><td>Publish</td><td><code>rt/rbq/cmd/switch_control_mode</code></td><td><code>Bool_</code></td></tr></tbody></table><h2 id="key-implementation-notes" tabindex="-1">Key implementation notes <a class="header-anchor" href="#key-implementation-notes" aria-label="Permalink to &quot;Key implementation notes&quot;">​</a></h2><ul><li><strong><code>gait_transition</code> flag</strong>: A <code>threading.Lock</code>-protected <code>consume_gait_pending()</code> method ensures the flag is consumed exactly once per gait change — mirrors the C++ <code>std::atomic::exchange()</code> pattern.</li><li><strong><code>switchControlMode</code></strong>: Published once at startup after a 200 ms delay. If not published, the robot ignores <code>HighLevelCommand</code>.</li><li><strong>Timing</strong>: The control loop uses <code>time.monotonic()</code> and <code>time.sleep()</code> for 20 ms pacing. On slip, it resets <code>next_tick</code> to avoid clock drift.</li><li><strong>No RT thread</strong>: Unlike the C++ version, no real-time thread is used. <code>sudo</code> is not required.</li></ul><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="/RBQ/software/sdk/cpp/high-level.html">High Level Command (C++)</a></li><li><a href="/RBQ/software/sdk/python/sport-client.html">Sport Client (Python)</a></li><li><a href="/RBQ/software/sdk/python/low-level.html">Low Level (RL Policy) (Python)</a></li><li><a href="/RBQ/software/sdk/python/overview.html">Python SDK Overview</a></li></ul>`,28)])])}const k=e(o,[["render",n]]);export{g as __pageData,k as default};
